-- The log of the admin gets `person.edit` (#1053): the editors gave a person a line or a country on the work list of the admin. It is a new value at the end of the list, so no row changes.
-- To undo it on the host: remove the rows with `person.edit` from `audit_log`, then put the list of actions back as it was with `ALTER TABLE audit_log MODIFY COLUMN action enum(...)` without the last value.
-- The statement can run again: MariaDB cannot undo DDL, so a migration that stopped halfway finishes on the next start.
ALTER TABLE `audit_log` MODIFY COLUMN `action` enum('item.hide','item.show','item.approve','item.unapprove','article.create','article.update','article.publish','article.unpublish','match.edit','match.undo','match.caught-up','match.differs','match.take-over','match.keep','match.add','match.delete','stadium.save','stadium.reset','club-name.save','club-name.reset','player.stats-differ','player.stats-take-over','player.stats-keep','player.add','player.edit','player.remove','player.field-take-over','player.field-keep','person.edit') NOT NULL;